MAPPED = {'confidentialite': ('accord_confidentialite', COMMUN, 'Accord de confidentialité'), 'lettre_intention': ('lettre_intention', COMMUN, 'Lettre d’intention'), 'promesse_fonds': ('compromis_fonds', FONDS, 'Promesse ou protocole de fonds')}
ORDER = {COMMUN: 'Commun', FONDS: 'Fonds de commerce', BAIL: 'Droit au bail'}


def references():
    """Les 43 références du catalogue minimal : identifiant, famille, titre et modèle de la bibliothèque qui les porte."""
    out = [{'reference': t['id'], 'famille': t['famille'], 'titre': t['titre'], 'modele': t['id']} for t in TEMPLATES]
    out += [{'reference': k, 'famille': v[1], 'titre': v[2], 'modele': v[0]} for k, v in MAPPED.items()]
    return out
